export const skillFiles: Record<string, string> = {
  "brclio-pay-integrate/SKILL.md": "---\nname: brclio-pay-integrate\ndescription: 为一个已授权产品接入 Brclio Pay，完成后端收款、客户端付款后刷新及授权范围内上线，或更新该产品商品、价格和回调配置。使用单产品临时授权，保留现有登录、订单、权益及其他支付集成。\n---\n\n# Brclio Pay 单产品接入\n\n为当前任务指定的一个产品完成服务端下单、收银台跳转、验签回调、幂等权益开通和客户端状态更新，或最小修改该产品已经登记的支付配置。通用 Skill 不包含凭证；当前任务的临时接入令牌仅对一个产品及指定新增/修改操作有效，通常两小时后到期。\n\n如果只有复制来的任务提示词、没有附件，用其中的支付中心地址请求 `GET /api/integration/v1/skill.zip`，通过 `Authorization: Bearer …` 传递同一个临时令牌。下载到当前任务专用、被 Git 忽略的临时目录后解压，读取包内 `SKILL.md`、引用文档并运行其中的 CLI。不要把令牌放进 URL/query、打开 verbose 请求日志，或自动安装到全局 Skill 目录；用户要求全局安装时再执行安装。\n\n## 先确认范围，再接入\n\n临时授权允许读取、生成计划及应用**指定产品**的 Brclio Pay 配置，不允许修改其他产品，不提供管理员密码、支付宝私钥或 GitHub 令牌。它不替代用户对目标产品仓库的访问、编辑和部署授权；仅在当前任务已授权的仓库及工作范围内行动。用户已明确要求接入或更新时，可继续完成该范围内的计划和应用，无须重复征求确认。\n\n1. 从任务上下文取得产品 ID、新增或修改操作范围、支付中心地址、授权到期时间及 `brp_int_…` 临时令牌。支付环境从 context.paymentMode 核实，`mode: create/update` 是接入操作类型，不是正式/沙箱环境。将令牌仅放入当前进程的 `BRCLIO_PAY_INTEGRATION_TOKEN` 环境变量，不写入 Skill、源码、计划文件、日志或提交。不要把它作为命令行参数或输出凭证。\n2. 对目标仓库运行 `node scripts/inspect-platform.mjs /绝对路径/产品仓库`，再读取有关业务源文件。扫描器只输出路径、能力标签及候选套餐证据行号，不读取 dotenv、私钥、凭证文件，不输出源代码或价格值；候选位置不是已经证实的套餐。先识别用户认证、业务订单、价格、权益存储、已有支付提供方与 webhook 处理，再决定接入位置。保留已有行为，避免另建一套不关联用户的演示订单。\n3. 读取 [接入协议](references/integration.md)，运行 `node scripts/integration-client.mjs context` 获取实际产品配置和版本。版本为 `context.client.version`，新产品为 `absent`；context 同时包含 `domainMode`、`pricingMode` 与 `allowedOrigins`，按下述域名模式处理。工具默认隐藏凭证；只有用户任务需要在目标后端落地 Secret 时，才使用 `context --credentials-file /已被Git忽略的路径/.env.brclio-pay` 写入已存在产品的凭证。新产品在 apply 后才产生凭证，可使用 `apply PLAN_ID --credentials-file /已被Git忽略的路径/.env.brclio-pay`。文件独占创建且权限为 0600；不要覆盖既有 Secret 文件。\n\n## 商品来源：读取项目或人工指定\n\n任务中的 `pricingMode` 与 create/update、live/sandbox 无关。没有指定时使用 `detect`。\n\n- **detect：读取项目现有套餐。** 从扫描器的 `catalogCandidates` 定位后端商品配置、套餐数据结构/迁移及定价文档，并实际阅读相关代码。已有只读数据库权限时，只查询必要的商品/套餐记录，不导出客户、订单或凭证。以前述业务依据确认 SKU、金额、币种、权益及有效期，再和前端定价页核对。本中心只有 CNY；不能把 USD 等外币金额照抄为人民币，也不能自行换汇，需用户给出明确的人民币收费规则。报告路径与行号或脱敏的查询出处、商品映射和待确认项；前端文案、测试夹具、旧注释或依赖锁文件不能单独作为真实收费依据。若后端、数据库和文档互相冲突，先问用户，不替其选价。\n- **manual：人工指定规则。** 使用用户在当前任务明确给出的真实商品、价格、权益及有效期；仍检查旧套餐和订单逻辑，避免重复 SKU 或影响已有付费用户。用户明确指定的规则优先于项目旧展示；发现关键差异时报告，并同步调整目标产品。缺少必要业务规则就问用户，不补造金额或权益。\n\n两模式都先生成商品对应关系，再提交计划。目录 SKU 必填 `subject`（名称）与 `amount`（人民币两位小数字符串）；可选 `enabled`（默认 true，false 停售）、`description`（最多 500 字）、`entitlement`（最多 1000 字，说明权益与有效期）。`entitlement` 是说明，实际开通规则仍由目标产品后端维护。已有平台更新保留未请求修改的商品字段。\n\n## 域名来源：自动发现或固定范围\n\n来源只包含 `https://`、host 与可选端口；具体 webhook/返回页路径可以根据目标项目路由自行设计。例如来源 `https://xhs.download.brclio.com` 可使用 `/api/payments/brclio/webhook` 和 `/billing/return`，不需要为每条路径另加授权。\n\n- **`domainMode=auto`：** 用户允许 AI 为**指定产品**自动发现或设计所需的公网 HTTPS 来源。先检查该项目实际域名、部署与后端路由，再把必要的新来源连同配置提交 plan；核对 `addedOrigins`、回调和返回页后按当前任务授权应用，无需逐个要求用户再次签发。来源在 apply 时纳入该授权记录，管理员可在后台查看实际平台域名及授权记录。不要虚构已部署的域名、改动 DNS 或申请新域名来使配置通过，也不要为省事引入无关或过宽通配来源；缺少目标项目部署权限时仍需说明阻塞。\n- **`domainMode=fixed`：** 新增或变更地址必须在 `context.allowedOrigins` 中。只有管理员显式授权的通配来源允许其匹配的子域名；不同 host 不会自动获得权限。需要额外后端 host 时列出完整来源，请管理员补充并重新生成任务。\n\n旧授权未带 `domainMode` 时按 fixed 处理。两种模式都限一个产品、最长两小时、可撤销，不能访问其他产品或扩大目标仓库权限。`pricingMode` 以 context 返回值为准，旧授权缺省 detect。\n\n## 新产品与已有产品\n\n- **新产品：** 根据真实业务 SKU、固定金额、公开 HTTPS webhook 和返回 origin 生成配置；创建时使用 `expectedVersion: \"absent\"`。产品 ID 必须等于授权目标。\n- **已有产品：** 以 context 返回的当前配置和版本为基线，只修改用户要求的字段。保留未请求变更的 SKU、返回域名、回调和启用状态；不旋转凭证，不重置其他支付提供方。版本冲突后重新读取并合并一次；仍有冲突、目标不符或授权过期时停止相关应用，并说明所需的新授权或业务决定。\n\n将完整的目标配置及 `expectedVersion` 写入**不含凭证**的 JSON 计划文件，运行 `node scripts/integration-client.mjs plan /路径/plan.json`。比较返回的 `before` 与 `after`，检查目标产品、环境及有效期，再用 `node scripts/integration-client.mjs apply PLAN_ID` 应用这个计划。计划以版本比较防止覆盖并发更新；不要绕过计划、伪造版本或扩大令牌权限。\n\n商品改价只作用于之后创建的订单，历史订单金额保持原值。改价或改权益前，检查目标产品是否用当前套餐金额校验旧通知；同步安排目标产品展示、购买资格、下单校验与订单快照，不能让新支付金额被产品旧价格拒绝，也不能用新权益覆盖旧订单承诺。更改 webhook 会影响尚未投递的付款通知；必须确认新接收端已就绪、保留旧端过渡或说明未处理通知的影响。停用商品/产品只阻止新购买，已有订单继续验签、查单和开通；不要删除业务记录。\n\n## 产品后端实现\n\n按实际框架适配 [服务端客户端模板](assets/payment-client.mjs) 与 [回调模板](assets/webhook-handler.mjs)，不要把 Node 专用文件直接打包到浏览器或移动客户端。其他语言实现相同协议即可。\n\n- 实现产品后端通过长期 API Secret 签名读取 `GET /api/v1/catalog`（模板 `pay.catalog()`）。校验所属产品、mode 与 `currency=CNY`，通过产品自己的后端向网页/客户端提供公开商品；不把支付 Secret 发给前端。展示与下单读取启用商品，不缓存或设置明确短缓存，避免把价格固化在静态构建里。已实现目录读取的产品可读取后台新价；旧产品须先完成这次改造。`acceptingPayments=false` 时保留报价、旧单查单和通知处理，暂停新购买并显示收款未开放；刷新目录恢复。目录检查后仍可能返回 `PAYMENTS_DISABLED`，按固定脱敏提示处理并保留原业务订单，不盲目重试。兼容旧服务缺少此字段，不能把目录可读当成已开放收款；商品版本不因开关变化而改变。\n- 用户由原产品登录态认证，业务后端根据商品与购买资格创建业务订单，保存付款订单与用户关联，并快照该笔订单的 SKU、金额、实际权益规则及有效期。`createOrder` 响应的 SKU/amount 是当笔支付订单权威。读取目录和下单之间可能改价：若响应与用户已确认报价不同，停止放出 checkoutUrl，让用户确认新报价后用新业务订单重建；不能暗中涨价或继续按旧价验签。权益说明仅是文案，实际产品开通规则仍须实现并同步修改。\n- 付款期限为创建后 10 分钟，已有待付款订单同样按原创建时间计算；到期禁止发起付款。重复创建不会延长期限，已关闭或到期后重购必须使用新业务订单号。中心定时或主动刷新会先核实上游付款/关单状态，异常时可能暂为 `PENDING`，产品不能把到期 `PENDING` 视为仍可付款。历史已签发的 30 分钟支付宝链接不能追溯改写其 `time_expire`，仍需上游关单；`CLOSED` 后保留原订单及迟到有效付款的幂等履约路径，不能因业务侧已过期而拒绝真实付款通知。\n- 桌面和 Android 首版打开支付中心的 HTTPS 收银台；前端或安装包不保存 API/webhook Secret。原生支付宝 SDK、深链自动回跳需要独立实现与验证。\n- webhook 先验签、校验环境、所属产品、业务订单、SKU、金额，再在同一持久化事务内去重事件、开通权益并更新业务订单。重试同一事件应返回成功；不能用内存 Set 作为生产去重表。\n- HTTPS 返回页只携带订单引用。产品后端查单确认状态；回跳参数、客户端“成功”提示都不能开通权益。沙箱事件只能用于测试，正式权益接收端默认拒绝它。\n\n## 完成付款后的客户端同步\n\n不能把“打开付款页”“中心已 PAID”或“回调已送达”作为接入完成。产品自己的已认证查单接口应分别返回付款状态和**该业务订单实际已提交的权益状态**，校验当前用户归属，不能只拿账号原本已有的会员资格代替这笔订单的履约证据。\n\n- 下单成功后保留当前用户与业务订单的关联，网页返回、桌面窗口 focus、移动应用 resume 时立即查询产品后端；等待付款时也进行有界低频查询。`PAID` 但权益未确认时继续等待，不停止在“已付款，稍后查询”。可按 [完成状态模板](assets/payment-completion.mjs) 适配已有框架；这是调用产品后端的无密钥客户端模板，不是签名 SDK。具体响应映射见 [接入协议](references/integration.md)。\n- 产品后端确认该订单实际权益提交后，重新获取账号/权限，更新会员标识、到期时间和功能权限，关闭或更新付款弹窗。客户端等待超时不等于服务端订单已关闭，保留订单与手动查询，不提示重复付款；收到 `CLOSED` 时停止本轮等待，用户明确重购时新建业务订单并保留旧单查证。隐藏时暂停，离开/退出/切换账号时清理请求和监听，忽略旧账号迟到结果。重启后从该用户的业务订单恢复，不能只依赖组件内存。\n- 支付中心会在 live 订单通知送达后倒计时返回已登记 HTTPS 页面；这不保证桌面应用被操作系统拉回前台。没有已验证的 App Links / Universal Links 或产品自己的安全唤起方案时，以应用回到前台查单作为必需路径，不把新增自定义 scheme 当作支付凭据。\n\n测试应覆盖付款晚于回跳、PAID 后回调延迟、10 分钟到期禁止付款、关闭后以新业务订单重购、旧单迟到有效付款仍幂等履约、外部浏览器返回桌面、隐藏/恢复、账号切换、等待超时手动恢复，以及重复回调只开通一次。使用假的上游支付和测试订单，不自行执行真实付款。\n\n## 在产品项目完成上线与开放\n\n任务已授权接入、部署并开放收款时，继续在**产品项目**完成后端 Secret 配置、webhook/查单/返回页和网页或安装包发布，再核实线上目录与实际路由；不能停在中心 plan/apply 成功。新建产品可在计划中使用 `enabled:true`；已有产品保留启用状态，除非本次任务明确授权恢复收款。上线前用产品自己的功能开关限制尚未完成验证的购买入口，避免公开一个无法履约的入口。\n\n当 `/api/health` 的 `ready/acceptingPayments` 和产品签名目录的 `enabled/acceptingPayments` 均为 true、环境正确且商品可售，完成产品检查后即可按当前授权开放该产品入口，**不需要返回支付仓库再次部署或改总开关**。签名目录才反映该产品是否允许收款，不能仅凭公共 health 判断。总开关 false、商户权限缺失或外部发布权限不足时，明确指出具体阻塞；临时产品授权不能修改总开关或商户配置。固定来源不足、授权到期/撤销或操作类型不符等情况需要新的受限授权，不索取全账号凭证。create 授权成功创建后，只能重放原计划；之后若要修改回调、来源或商品，需要 update 授权，即使原 create 令牌尚未到期或允许 auto 来源。部署前先确认路由与商品，减少这类返工；令牌到期不影响已交付的长期凭证和正常支付。\n\n部署与人工实付验收按当前用户授权进行；让用户在产品项目亲自完成一笔小额付款后，核对中心付款、回调以及产品实际权益和客户端显示。不能自动点击付款，不能把模拟测试写成真实到账。对需要安装包的产品分别报告源代码、后端、网页、安装包发布与安装后行为；网页发布不会更新用户已安装的旧前端。\n\n最终说明改动的产品、配置版本、代码入口、验证结果及仍需用户完成的步骤。不要展示任何长期或临时凭证，也不要把付款通知已送达宣称为产品实际权益已验证开通。\n",
  "brclio-pay-integrate/references/integration.md": "# Brclio Pay 接入协议\n\n## 单产品接入授权\n\n`BRCLIO_PAY_BASE_URL` 默认为 `https://pay.bornforthis.cn`。临时令牌通过 `Authorization: Bearer …` 发送，仅用于以下接入管理 API，不用于正常支付请求。\n\n| 方法与路径 | 请求 / 作用 |\n| --- | --- |\n| `GET /api/integration/v1/skill.zip` | 使用同一个临时 Bearer 授权下载通用 Skill 包；不通过 URL 传递凭证，解压到任务临时目录即可使用 |\n| `GET /api/integration/v1/context` | `{clientId,mode,paymentMode,pricingMode,domainMode,allowedOrigins,expiresAt,client,credentials,payBaseUrl,docsUrl}`；`client` 为当前配置或 null，凭证只属于目标产品，不输出它 |\n| `POST /api/integration/v1/plan` | `{ \"config\": {…}, \"expectedVersion\": \"absent\"或当前版本 }`；返回 `{planId,clientId,mode,baseVersion,expiresAt,before,after,addedOrigins}` |\n| `POST /api/integration/v1/apply` | `{ \"planId\": \"…\" }`；返回 `{client,credentials,appliedAt}`，应用同一授权目标的有效计划 |\n\n`mode` 为 `create` 或 `update`，表示授权操作；`paymentMode` 为 `live` 或 `sandbox`，表示实际支付环境。`pricingMode=detect/manual` 指项目读取/人工指定商品规则；`domainMode=auto/fixed` 指允许 AI 为该产品增加必要来源/固定域名范围。缺省 pricingMode=detect、domainMode=fixed，以兼容旧授权。`ClientView` 为 `{id,name,webhookUrl,returnOrigins,skus,enabled,version}`；版本是目标配置的 SHA-256。使用 `context.client?.version ?? 'absent'` 作为 expectedVersion。新产品 context 中 client / credentials 都为 null；创建应用后才返回凭证。\n\nfixed 模式新增/变更来源须满足 context.allowedOrigins。auto 模式允许空初始来源：AI 根据目标项目路由提交合法公网 HTTPS 来源，plan 用 `addedOrigins` 展示，apply 原子纳入该授权记录（累计最多 100 个），管理员可查看。自动来源模式不授予其他平台、DNS、域名购买或产品仓库权限；不应添加无关来源。两种模式都可以在合法来源内设计具体路径。\n\n根据实际 context 响应使用返回的产品 ID、环境和版本，不把示例当作现状。授权过期/撤销（401、403）、目标不符、计划过期或并发版本冲突时停止依赖该结果的变更；不要反复重试写入。需要时重新读取 context，保留用户已完成的实现。\n\ncreate 成功后重放同一 plan 可幂等取得原结果；修改已存在产品需要 update 授权，不能用尚未过期的 create 令牌新建修改计划，domainMode=auto 也不改变操作类型。应用前确认最终回调路由与商品；临时授权到期不撤销已交付的长期凭证，不影响产品后端正常支付。\n\n计划的 `config` 不包含凭证，结构如下；使用真实业务内容替换示例：\n\n```json\n{\n  \"config\": {\n    \"id\": \"target-product-id\",\n    \"name\": \"产品名称\",\n    \"webhookUrl\": \"https://product.example/api/brclio-payment\",\n    \"returnOrigins\": [\"https://product.example\"],\n    \"skus\": {\"pro\": {\"subject\": \"产品 Pro\", \"amount\": \"9.90\", \"enabled\": true, \"description\": \"真实商品说明\", \"entitlement\": \"真实权益及有效期\"}},\n    \"enabled\": true\n  },\n  \"expectedVersion\": \"absent\"\n}\n```\n\n金额为大于零、两位小数的 CNY 字符串。登记明确的 HTTPS origin；不要为了省事开放所有域名。`brclio.com` 和子域名可按业务配置，但统一支付域名不替代支付宝对经营主体、商品和域名的审核。\n\n商品必填 subject（最多 120 字）和 amount；可选 enabled（默认 true，false 停售）、description（最多 500 字）、entitlement（最多 1000 字）。权益说明不是支付中心的自动开通逻辑；目标产品必须实现对应规则。detect 先从后端商品配置、已有只读权限的套餐记录及定价文档取证，再与前端交叉核对；manual 按用户明确规则填写。缺失或冲突时询问用户，不编造。改价同时安排产品展示/下单和金额校验更新，旧业务订单按创建时金额与权益快照继续处理。\n\ndetect 必须确认币种；中心只有人民币 CNY。项目现有 USD 等外币金额不能直接当人民币或自行换汇，需用户提供人民币收费规则。\n\n## 正常支付 API\n\n正常支付使用**产品长期 API Secret 的 HMAC**，不是临时接入令牌：\n\n- `GET /api/v1/catalog`：读取当前产品公开目录 `{clientId,name,enabled,acceptingPayments,mode,currency:'CNY',version,skus:{SKU:{subject,amount,enabled,description?,entitlement?}}}`，不含凭证。`enabled` 为产品状态，`acceptingPayments` 为总开关与该产品均允许新购买；关闭收款仍可读配置齐全的目录。`acceptingPayments=false`、产品停用或商品停售应停止新购买，保留价格、已有订单查单与权益处理。刷新目录可恢复购买；开关变化不改变商品版本。此状态不证明支付宝权限、到账或实际开通。\n- `POST /api/v1/orders`，JSON `{productOrderId,sku,returnUrl}`；返回付款订单与包含令牌 fragment 的 `checkoutUrl`。\n- `GET /api/v1/orders/:id`，读取持久化状态。\n- `POST /api/v1/orders/:id/refresh`，未到期时请求受 60 秒节流的补偿查询，到期时执行关单收尾，可发送 `{}`。\n\n头字段为 `X-Brclio-Client`、`X-Brclio-Timestamp`（Unix 秒）、`X-Brclio-Nonce`（`[A-Za-z0-9_-]{16,80}`）和 `X-Brclio-Signature`（十六进制 HMAC-SHA256）。允许时间偏差为 5 分钟。服务端 API 不接受 query string。\n\n签名原文为 `METHOD_UPPERCASE + '\\n' + pathname + '\\n' + timestamp + '\\n' + nonce + '\\n' + sha256_hex(rawBody)`，末尾无额外换行。GET 的 body 为空字符串。签名后不能改变 JSON 空白、顺序或编码。\n\n`(clientId, productOrderId)` 保持唯一。相同内容重复创建取得同一付款订单；修改 SKU 或返回地址应使用新的业务订单号。保持原产品业务订单、用户和购买资格为权威，不让客户端改价。付款状态包括 `PENDING`、`PAID`、`CLOSED`；权益投递状态 `delivered` 仅表示产品确认接收通知。\n\n订单返回 `expiresAt`，付款期限为创建后 10 分钟，旧 `PENDING` 同样按原 `createdAt + 10 分钟` 收尾。到期立即禁止发起付款；幂等重试不会延长原期限，已关闭或到期后重购须新建业务订单号。中心每 5 分钟的后台任务或主动刷新会先验签查询支付宝：已付正常确认；存在未付款交易时先取得关单成功确认；确认交易不存在或已关闭才记录 `CLOSED`。查询/关单异常时暂留 `PENDING` 并重试，不能继续付款。关闭与移出补查队列、报表更新同事务，成功后停止周期补查；无积压且上游正常时，通常在创建后约 10–15 分钟关闭。\n\n到期收尾不预写 `lastCheckedAt`，查询或关单失败不产生仅更新时间戳的提交。历史已签发的 30 分钟支付宝链接不能追溯改写其 `time_expire`，本地到期拒绝重新发起不能代替上游关单。保留旧业务订单与历史金额、权益快照；迟到有效付款通知仍可将中心 `CLOSED` 恢复为 `PAID`，产品不能只因本地到期或已关闭就拒绝真实付款，仍须验签核对并幂等履约。\n\n模板提供 `pay.catalog()`。产品通过自己的后端读取目录展示/校验启用商品，不缓存或明确短缓存；不能把支付凭证给客户端，也不能将价格长期固化在构建产物里。只有实现了目录读取的产品会读取后台新价，旧产品不会凭空自动更新。目录 entitlement 仅说明，实际开通规则修改仍需产品实现。`acceptingPayments` 是兼容新增字段，旧服务未返回不代表已开放收款；创建/发起付款仍可能返回 `503 / PAYMENTS_DISABLED`。模板错误提供 `code` 和 `status`，产品应以固定脱敏文案说明收款未开放，保留原业务订单供恢复后幂等重试，不连续盲重试，也不影响旧单通知和查单。\n\n目录读取与创建订单之间可能发生改价。产品业务订单记录用户已确认报价及实际权益规则快照，再核对 `createOrder` 响应的 SKU/amount（当单权威）：不一致就不向用户放出 checkoutUrl，提示确认新报价，并以新业务订单号重建。确认一致后持久保存支付订单 ID、金额及权益快照，再交付收银台链接。旧 webhook 按该笔业务订单快照核对，禁止拿最新目录验证旧付款。\n\n## 产品 webhook 与持久开通\n\n付款事件是至少一次投递。请求头：\n\n- `X-Brclio-Event`：稳定事件 ID。\n- `X-Brclio-Timestamp`：此次投递的 Unix 秒。\n- `X-Brclio-Signature`：`HMAC-SHA256(webhookSecret, timestamp + '.' + rawBody)` 的十六进制值。\n\n验证原始请求体后解析。事件结构为 `{id,type:'payment.paid',mode:'live'|'sandbox',createdAt,data:{orderId,productOrderId,clientId,sku,amount,currency:'CNY',tradeNo,paidAt}}`。要求 header 事件 ID 与 body 一致，环境与当前产品接收端一致，订单和金额与原产品存储一致。默认只接受 live 事件；隔离的测试接收端才能接受 sandbox。\n\n在产品数据库事务中：读取对应业务订单和用户、核对 SKU/金额/环境、以事件 ID 或付款订单 ID 唯一去重、写入权益、更新业务订单。已经提交的重复事件也返回 2xx；临时数据库故障返回非 2xx，让支付中心重试。先返回成功再异步但无持久保证地开通会丢单。\n\n付款回跳 URL 不是权益凭证。跨浏览器、未安装支付宝、系统回到不同应用时仍依赖后端 webhook/查单；不要承诺原生应用必然自动回到前台。\n\n## 付款完成与客户端刷新\n\n支付页对 `PAID / fulfillmentStatus=pending` 继续有界 GET 查询；通知送达后，live 订单倒计时返回已登记 HTTPS 页面，可取消自动返回，sandbox 不自动返回。`delivered` 只证明接收端返回 2xx；原生应用还须在 focus/resume 时主动刷新。\n\n`assets/payment-completion.mjs` 是浏览器安全的等待模板。`queryOrder` 必须调用产品自己的已认证后端，响应适配为：\n\n```json\n{\"productOrderId\":\"当前用户的业务订单号\",\"mode\":\"live\",\"paymentStatus\":\"PAID\",\"entitlementStatus\":\"pending\"}\n```\n\n付款状态为 `PENDING / PAID / CLOSED`，权益状态为 `pending / active`。产品后端校验用户归属、环境、SKU、金额与历史快照，只有**该订单实际权益事务已提交**才返回 active；不能把中心 delivered 或账号原本已有会员映射成此订单 active。模板在 live + PAID + active 时先执行 `refreshAccount`，再报告 confirmed；这个回调应重新读取当前用户的账号与实际权限并更新 UI。模板不发起付款、不直接访问支付中心，也不包含任何支付密钥。\n\n```js\nimport { createPaymentCompletionWatcher } from './payment-completion.mjs';\nconst watcher = createPaymentCompletionWatcher({\n  productOrderId: savedBusinessOrderId,\n  queryOrder: (id, { signal }) => productApi.getMyPaymentStatus(id, { signal }),\n  refreshAccount: ({ signal }) => productApi.reloadCurrentAccountAndPermissions({ signal }),\n  onState: ({ status, code }) => renderPaymentProgress(status, code),\n});\nawait watcher.start();\n// 运行中手动查询用 check()，超时/登录恢复后 start()。\n// 离开、卸载或退出/切账号前 dispose()，新账号使用新实例。\n```\n\n`productApi` 与 `renderPaymentProgress` 需要适配产品现有接口/UI。queryOrder 返回上述归一化结构；两个适配器都要传递 signal，并在写入账号缓存前复核当前会话。移动端按自身 resume 生命周期启动/恢复等待并清理监听。状态回调为 `{productOrderId,status,code?}`，status 是 pending/confirming/confirmed/closed/error/timeout；code 为固定脱敏错误标识。\n\n下单后保存按用户隔离的待核实业务订单引用，别记录 checkoutUrl 的访问 token。网页返回、桌面 focus、移动 resume、重启恢复都启动同一等待流程；默认每 15 秒、最多 5 分钟，隐藏暂停、恢复立即查询、避免并发。PAID 而权益 pending 时继续等待，确认后刷新徽标、到期时间和实际功能权限。客户端等待超时不等于服务端订单已关闭，保留原订单与手动查询，不提示重复付款；收到 `CLOSED` 时结束本轮等待，可提供以新业务订单号重新购买的入口，保留原单查证与迟到有效付款处理。退出/切换账号 dispose 旧等待，忽略迟到结果。安装包产品必须发布并验证安装后的新前端，网页发布不会更新旧安装包。\n\n## 从产品项目部署和开放\n\n用户已授权接入、部署与上线时，在产品仓库完成 Secret、回调/查单/返回页部署和客户端发布，不停在 plan/apply 成功。中心 health 的 ready/acceptingPayments、签名目录的 enabled/acceptingPayments 均为 true、环境与可售商品匹配后，可按授权直接开放产品购买入口，无须回支付仓库重复改总开关或部署。新产品可在创建计划中登记 enabled:true；已有产品除本次任务明确要求恢复外保留状态。上线前限制未完成验证的购买入口。\n\n总开关 false 或商户能力缺失超出单平台授权，只报告具体阻塞，不修改商户或索取全账号凭证。固定来源不足、授权过期或产品发布权限不足同样明确列出必要步骤。真实付款由用户在产品项目人工完成，分别核对中心付款、通知、产品实际权益和客户端显示。测试覆盖回调延迟、付款晚于回跳、10 分钟到期禁止付款、关闭后新业务订单重购、旧单迟到有效付款幂等履约、focus/resume、重启恢复、退出/切换账号、等待超时手动恢复及重复回调。\n",
  "brclio-pay-integrate/scripts/inspect-platform.mjs": "import { readdir, readFile, realpath, lstat } from 'node:fs/promises';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\n\nconst ignored = new Set(['.git', '.codex', '.agents', 'node_modules', 'vendor', 'dist', 'dist-pages', 'build', 'out', 'artifacts',\n  '.next', '.nuxt', '.output', '.svelte-kit', '.vercel', '.wrangler', '.turbo', '.cache', 'coverage', '.venv', 'venv']);\nconst sensitive = name => /^\\.env(?:\\.|$)/i.test(name) || /(?:secret|credential|password|private[-_]?key|token)/i.test(name)\n  || /\\.(?:pem|key|p12|pfx|crt|keystore|sqlite|db|log)$/i.test(name);\nconst source = /\\.(?:[cm]?[jt]sx?|py|go|rs|java|kt|php|rb|vue|svelte|json|md|mdx|ya?ml|toml|sql|prisma)$/i;\nconst providers = { alipay: /alipay|支付宝/i, stripe: /stripe/i, paddle: /paddle/i, lemonsqueezy: /lemon.?squeezy/i, wechat: /wechat.?pay|weixin.?pay|微信支付/i, paypal: /paypal/i };\nconst capabilities = { authentication: /auth|session|login|登录/i, orders: /order|checkout|订单/i, entitlements: /entitlement|subscription|license|membership|权益/i, webhook: /webhook|callback|notify|回调/i };\nconst catalogPath = /catalog|plan|pricing|price|product|sku|billing|subscription|membership|套餐|价格/i;\nconst catalogIdentifier = /\\b(?:skus?|products?|plans?|packages?|tiers?|product_?id|plan_?(?:id|code))\\b|套餐|商品编号/i;\nconst catalogAmount = /\\b(?:amount|prices?|cents|unit_?amount|monthly_?price|yearly_?price)\\b|价格|金额|售价/i;\nconst catalogEntitlement = /\\b(?:entitlements?|credits?|quota|duration|validity|expiry|expires|features?|interval|period|days?|months?|years?|limits?)\\b|权益|有效期|额度|次数/i;\nconst catalogCurrency = /\\b(?:currency|cny|rmb|usd|eur|gbp|hkd)\\b|人民币|美元|港币|欧元|[¥￥$]/i;\nconst nonBusinessCatalog = /(?:^|\\/)(?:__tests__|tests?|fixtures?|examples?|artifacts|mocks?)(?:\\/|\\.)|(?:^|\\/)(?:package(?:-lock)?\\.json|yarn\\.lock|pnpm-lock\\.yaml|composer\\.lock)$/i;\n\nfunction catalogKind(filename) {\n  if (/\\.(?:sql|prisma)$/i.test(filename) || /(?:^|\\/)(?:schema|migrations?)(?:\\/|\\.)/i.test(filename)) return 'data-schema';\n  if (/\\.(?:md|mdx)$/i.test(filename)) return 'documentation';\n  if (/\\.(?:vue|svelte|tsx|jsx)$/i.test(filename) || /(?:^|\\/)(?:components?|pages?|views?|ui)(?:\\/|\\.)/i.test(filename)) return 'display';\n  if (/\\.(?:json|ya?ml|toml)$/i.test(filename) || /(?:^|\\/)(?:server|api|config|catalog|lib)(?:\\/|\\.)/i.test(filename)) return 'server-config';\n  return 'source';\n}\n\n// Locations are hints for the AI to read, never extracted prices or authoritative claims.\nfunction locateCatalog(filename, content) {\n  if (nonBusinessCatalog.test(filename)) return [];\n  const lines = content.split(/\\r?\\n/);\n  const locations = [];\n  for (let index = 0; index < lines.length; index++) {\n    if (!catalogAmount.test(lines[index])) continue;\n    const nearby = lines.slice(Math.max(0, index - 4), index + 5).join('\\n');\n    if (!catalogPath.test(filename) && !catalogIdentifier.test(nearby)) continue;\n    const signals = ['amount'];\n    if (catalogIdentifier.test(nearby)) signals.push('catalog');\n    if (catalogEntitlement.test(nearby)) signals.push('entitlement');\n    if (catalogCurrency.test(nearby)) signals.push('currency');\n    locations.push({ path: filename, line: index + 1, kind: catalogKind(filename), signals });\n  }\n  return locations;\n}\n\nexport async function inspectPlatform(directory) {\n  const root = await realpath(directory);\n  const files = [];\n  let skippedSensitive = 0;\n  let truncated = false;\n  async function walk(current, depth) {\n    if (depth > 16 || files.length >= 5000) { truncated = true; return; }\n    const entries = (await readdir(current, { withFileTypes: true })).sort((a, b) => a.name < b.name ? -1 : a.name > b.name ? 1 : 0);\n    for (const entry of entries) {\n      if (entry.isSymbolicLink() || ignored.has(entry.name)) continue;\n      if (sensitive(entry.name)) { skippedSensitive++; continue; }\n      const absolute = path.join(current, entry.name);\n      if (entry.isDirectory()) await walk(absolute, depth + 1);\n      else if (entry.isFile() && source.test(entry.name)) {\n        if (files.length >= 5000) { truncated = true; break; }\n        files.push({ absolute, relative: path.relative(root, absolute).split(path.sep).join('/') });\n      }\n    }\n  }\n  await walk(root, 0);\n  const matches = [];\n  const catalogCandidates = [];\n  let catalogTruncated = false;\n  let packageDependencies = [];\n  for (const file of files) {\n    if ((await lstat(file.absolute)).size > 256 * 1024) continue;\n    const content = await readFile(file.absolute, 'utf8');\n    const candidates = locateCatalog(file.relative, content);\n    if (catalogCandidates.length + candidates.length > 200) catalogTruncated = true;\n    catalogCandidates.push(...candidates);\n    const priority = { 'server-config': 0, 'data-schema': 1, documentation: 2, display: 3, source: 4 };\n    catalogCandidates.sort((a, b) => priority[a.kind] - priority[b.kind] || a.path.localeCompare(b.path) || a.line - b.line);\n    catalogCandidates.length = Math.min(200, catalogCandidates.length);\n    const foundProviders = Object.entries(providers).filter(([, pattern]) => pattern.test(content)).map(([name]) => name);\n    const foundCapabilities = Object.entries(capabilities).filter(([, pattern]) => pattern.test(file.relative)).map(([name]) => name);\n    if (foundProviders.length || foundCapabilities.length) matches.push({ path: file.relative, providers: foundProviders, capabilities: foundCapabilities });\n    if (file.relative === 'package.json') {\n      try {\n        const pkg = JSON.parse(content);\n        packageDependencies = [...new Set([...Object.keys(pkg.dependencies || {}), ...Object.keys(pkg.devDependencies || {})])].sort();\n      } catch { /* Inventory must not print malformed file contents. */ }\n    }\n  }\n  return { filesScanned: files.length, skippedSensitive, truncated, packageDependencies, matches, catalogCandidates, catalogTruncated };\n}\n\nif (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {\n  try {\n    if (process.argv.length !== 3) throw new Error();\n    process.stdout.write(JSON.stringify(await inspectPlatform(process.argv[2]), null, 2) + '\\n');\n  } catch { process.stderr.write('Unable to inspect repository. Supply one readable product repository path.\\n'); process.exitCode = 1; }\n}\n",
  "brclio-pay-integrate/scripts/integration-client.mjs": "import { readFile, realpath, open, constants } from 'node:fs/promises';\nimport { execFileSync } from 'node:child_process';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\n\nconst redact = value => Array.isArray(value) ? value.map(redact) : value && typeof value === 'object'\n  ? Object.fromEntries(Object.entries(value).map(([key, item]) => [key, /secret|token|password|private.?key/i.test(key) ? '[REDACTED]' : redact(item)])) : value;\n\nasync function writeCredentials(destination, data) {\n  const credentials = data.credentials;\n  const clientId = data.clientId ?? data.client?.id ?? data.config?.id;\n  if (typeof clientId !== 'string' || !/^[a-z0-9][a-z0-9_-]{1,63}$/.test(clientId)\n    || typeof credentials?.apiSecret !== 'string' || typeof credentials?.webhookSecret !== 'string'\n    || !/^[A-Za-z0-9_-]{32,512}$/.test(credentials.apiSecret) || !/^[A-Za-z0-9_-]{32,512}$/.test(credentials.webhookSecret)) throw new Error('Target credentials unavailable');\n  const parent = await realpath(path.dirname(path.resolve(destination)));\n  const filename = path.join(parent, path.basename(destination));\n  try { execFileSync('git', ['check-ignore', '-q', '--', filename], { cwd: parent, stdio: 'ignore' }); }\n  catch { throw new Error('Credential file must be untracked and Git-ignored'); }\n  const file = await open(filename, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | (constants.O_NOFOLLOW || 0), 0o600);\n  try { await file.writeFile(`BRCLIO_PAY_CLIENT_ID=${clientId}\\nBRCLIO_PAY_API_SECRET=${credentials.apiSecret}\\nBRCLIO_PAY_WEBHOOK_SECRET=${credentials.webhookSecret}\\n`); }\n  finally { await file.close(); }\n}\n\nexport async function runIntegrationClient({ argv, env = process.env, fetcher = fetch, output = value => process.stdout.write(value + '\\n') }) {\n  const [action, ...rest] = argv;\n  let credentialsFile;\n  const positionals = [];\n  for (let i = 0; i < rest.length; i++) {\n    if (rest[i] === '--credentials-file') {\n      if (credentialsFile || !rest[i + 1]) throw new Error('Invalid credential destination');\n      credentialsFile = rest[++i];\n    } else if (rest[i].startsWith('--')) throw new Error('Unknown option');\n    else positionals.push(rest[i]);\n  }\n  if (!['context', 'plan', 'apply'].includes(action) || positionals.length !== (action === 'context' ? 0 : 1)\n    || (credentialsFile && action === 'plan')) throw new Error('Usage: context [--credentials-file PATH] | plan PLAN.json | apply PLAN_ID [--credentials-file PATH]');\n  const token = env.BRCLIO_PAY_INTEGRATION_TOKEN;\n  if (typeof token !== 'string' || !/^brp_int_[A-Za-z0-9_-]{20,2000}$/.test(token)) throw new Error('Scoped integration token required in environment');\n  const base = new URL(env.BRCLIO_PAY_BASE_URL || 'https://pay.bornforthis.cn');\n  if (base.protocol !== 'https:' || base.username || base.password || base.pathname !== '/' || base.search || base.hash) throw new Error('HTTPS payment origin required');\n  let payload;\n  if (action === 'plan') {\n    const raw = await readFile(positionals[0], 'utf8');\n    if (Buffer.byteLength(raw) > 128 * 1024) throw new Error('Plan file too large');\n    payload = JSON.parse(raw);\n    if (!payload || typeof payload !== 'object' || Array.isArray(payload) || !payload.config || typeof payload.expectedVersion !== 'string'\n      || /\"(?:apiSecret|webhookSecret|token|password|privateKey)\"\\s*:/i.test(raw)) throw new Error('Plan must contain config and expectedVersion without credentials');\n  } else if (action === 'apply') {\n    if (!/^[A-Za-z0-9_-]{1,160}$/.test(positionals[0])) throw new Error('Invalid plan ID');\n    payload = { planId: positionals[0] };\n  }\n  const response = await fetcher(new URL(`/api/integration/v1/${action}`, base), {\n    method: action === 'context' ? 'GET' : 'POST', redirect: 'error', signal: AbortSignal.timeout(20_000),\n    headers: { Authorization: `Bearer ${token}`, Accept: 'application/json', ...(payload ? { 'Content-Type': 'application/json' } : {}) },\n    ...(payload ? { body: JSON.stringify(payload) } : {}),\n  });\n  if (!response.ok) { await response.body?.cancel(); throw new Error(`Integration API HTTP ${response.status}; refresh scoped context or request renewed authorization`); }\n  const raw = await response.text();\n  if (Buffer.byteLength(raw) > 256 * 1024) throw new Error('Integration response too large');\n  const data = JSON.parse(raw);\n  if (credentialsFile) await writeCredentials(credentialsFile, data);\n  output(JSON.stringify(redact(data), null, 2));\n  return { credentialsWritten: !!credentialsFile };\n}\n\nif (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {\n  try { await runIntegrationClient({ argv: process.argv.slice(2) }); }\n  catch (error) {\n    // Provider error bodies and thrown network messages may include authenticated requests.\n    const safe = error instanceof Error && /^(Usage:|Invalid credential|Unknown option|Scoped integration|HTTPS payment|Plan |Invalid plan|Integration API HTTP|Integration response|Target credentials|Credential file)/.test(error.message)\n      ? error.message : 'Integration command failed; no credentials were printed.';\n    process.stderr.write(safe + '\\n'); process.exitCode = 1;\n  }\n}\n",
  "brclio-pay-integrate/assets/payment-client.mjs": "import {createHmac,createHash,randomBytes,timingSafeEqual} from 'node:crypto';\nconst hmac=(secret,value)=>createHmac('sha256',secret).update(value,'utf8').digest('hex');\nconst hash=value=>createHash('sha256').update(value,'utf8').digest('hex');\n\n/** SERVER ONLY. Never bundle this module or its secrets into a browser/desktop/Android app. */\nexport function createPaymentClient({baseUrl='https://pay.bornforthis.cn',clientId,apiSecret,fetcher=fetch}) {\n  if(!clientId || typeof apiSecret!=='string' || apiSecret.length<32)throw new Error('Payment client credentials required');\n  async function call(method,path,value) {\n    const body=value===undefined?'':JSON.stringify(value);\n    const timestamp=String(Math.floor(Date.now()/1000));const nonce=randomBytes(24).toString('hex');\n    const signature=hmac(apiSecret,[method,path,timestamp,nonce,hash(body)].join('\\n'));\n    const response=await fetcher(new URL(path,baseUrl),{method,redirect:'manual',signal:AbortSignal.timeout(30_000),headers:{'Content-Type':'application/json','X-Brclio-Client':clientId,'X-Brclio-Timestamp':timestamp,'X-Brclio-Nonce':nonce,'X-Brclio-Signature':signature},...(body?{body}:{})});\n    const result=await response.json();\n    if(!response.ok) {\n      const error=new Error(result.error?.message || `Payment API HTTP ${response.status}`);\n      error.code=typeof result.error?.code==='string' && /^[A-Z_]{1,80}$/.test(result.error.code)?result.error.code:'PAYMENT_API_ERROR';\n      error.status=response.status;\n      throw error;\n    }\n    return result;\n  }\n  function checkedId(id){if(!/^pay_[a-f0-9]{32}$/.test(id))throw new Error('Invalid payment order ID');return id;}\n  return {\n    // Read through the product backend; do not cache indefinitely in a frontend or build.\n    // acceptingPayments=false pauses new purchases; keep catalog prices and existing order/status flows.\n    catalog:()=>call('GET','/api/v1/catalog'),\n    // Orders expire 10 minutes after creation. Idempotent retries keep the original\n    // deadline/status; a deliberate repurchase needs a NEW productOrderId.\n    createOrder:({productOrderId,sku,returnUrl})=>call('POST','/api/v1/orders',{productOrderId,sku,returnUrl}),\n    getOrder:id=>call('GET',`/api/v1/orders/${checkedId(id)}`),\n    refreshOrder:id=>call('POST',`/api/v1/orders/${checkedId(id)}/refresh`,{})\n  };\n}\n\n/** Verify the ORIGINAL request body before parsing. Idempotent entitlement write must happen separately. */\nexport function verifyPaymentEvent({rawBody,headers,webhookSecret,clientId,mode='live',now=Date.now()}) {\n  if(typeof webhookSecret!=='string' || webhookSecret.length<32 || Buffer.byteLength(rawBody)>16_384)throw new Error('Invalid webhook configuration/body');\n  const timestamp=headers.get('X-Brclio-Timestamp') || '';\n  const signature=headers.get('X-Brclio-Signature') || '';\n  if(!/^\\d{10}$/.test(timestamp) || Math.abs(now/1000-Number(timestamp))>300 || !/^[a-f0-9]{64}$/i.test(signature))throw new Error('Expired or malformed webhook');\n  const expected=hmac(webhookSecret,timestamp+'.'+rawBody);\n  if(!timingSafeEqual(Buffer.from(expected,'hex'),Buffer.from(signature,'hex')))throw new Error('Webhook signature invalid');\n  const event=JSON.parse(rawBody);\n  if(event.type!=='payment.paid' || event.mode!==mode || event.id!==headers.get('X-Brclio-Event') || event.id!==`evt_${event.data?.orderId}` || !/^pay_[a-f0-9]{32}$/.test(event.data.orderId) || event.data.clientId!==clientId || event.data.currency!=='CNY' || !/^(?:0|[1-9]\\d{0,5})\\.\\d{2}$/.test(event.data.amount) || event.data.amount==='0.00' || !/^\\d{10,64}$/.test(event.data.tradeNo))throw new Error('Webhook event invalid');\n  return event;\n}\n",
  "brclio-pay-integrate/assets/webhook-handler.mjs": "import {verifyPaymentEvent} from './payment-client.mjs';\n/** Adapt to your server route. applyEntitlement must use a DURABLE transaction, never an in-memory Set. */\nexport function createWebhookHandler({clientId,webhookSecret,applyEntitlement}) {\n  if(typeof applyEntitlement!=='function')throw new Error('Durable entitlement transaction required');\n  return async request=>{\n    if(request.method!=='POST')return new Response('method not allowed',{status:405});\n    if(Number(request.headers.get('Content-Length') || 0)>16_384)return new Response('too large',{status:413});\n    const rawBody=await request.text();let event;\n    try{event=verifyPaymentEvent({rawBody,headers:request.headers,webhookSecret,clientId});}\n    catch{return new Response('invalid event',{status:401});}\n    try {\n      // In one transaction: match the stored order's owner, SKU and amount snapshot;\n      // never compare an old order with today's catalog price after a price change.\n      // Keep expired/closed business orders: a late valid paid event must still be\n      // reconciled and fulfilled once; local expiry alone cannot disprove payment.\n      // Insert event.id uniquely; grant its stored entitlement/version; mark the order paid.\n      // A duplicate committed event must also succeed. Never rely on redirect parameters.\n      await applyEntitlement(event);\n      return new Response('ok');\n    } catch{return new Response('retry later',{status:503});}\n  };\n}\n",
  "brclio-pay-integrate/assets/payment-completion.mjs": "/**\n * BROWSER SAFE. This module contains no payment credentials or payment-center calls.\n *\n * Adapt queryOrder(productOrderId, { signal }) to YOUR authenticated product backend.\n * That backend must check the current user's ownership of the business order and return:\n * { productOrderId, mode: 'live', paymentStatus: 'PENDING' | 'PAID' | 'CLOSED',\n *   entitlementStatus: 'pending' | 'active' }\n *\n * `active` means this order's real entitlement transaction has committed. A browser\n * return, PAID, or a delivered payment-center notification alone does not prove that.\n * Never expose an API/webhook secret, scoped integration Bearer, or center credential.\n * Throw an error with status 401/403 when the product session is no longer authorized.\n * Both adapters should respect signal and verify the session before updating local\n * account state. Call dispose() BEFORE logout/account switch or replacing this order.\n * This wait timeout is separate from the center's 10-minute payment deadline.\n * CLOSED ends this wait; keep the old order for late valid paid events/manual checks.\n * A deliberate repurchase must use a new business order ID, never reopen this one.\n */\nexport function createPaymentCompletionWatcher({\n  productOrderId,\n  queryOrder,\n  refreshAccount,\n  onState = () => {},\n  intervalMs = 15_000,\n  timeoutMs = 300_000,\n  requestTimeoutMs = 15_000,\n  windowTarget = typeof window === 'undefined' ? null : window,\n  documentTarget = typeof document === 'undefined' ? null : document,\n}) {\n  if (typeof productOrderId !== 'string' || !productOrderId.trim() || productOrderId.length > 128\n      || typeof queryOrder !== 'function' || typeof refreshAccount !== 'function' || typeof onState !== 'function'\n      || [intervalMs, timeoutMs, requestTimeoutMs].some(value => !Number.isFinite(value) || value <= 0)) {\n    throw new TypeError('Invalid payment completion watcher options');\n  }\n\n  let active = false;\n  let disposed = false;\n  let confirmed = false;\n  let generation = 0;\n  let inFlight = null;\n  let controller = null;\n  let pollTimer = null;\n  let deadlineTimer = null;\n  let lastPhase = 'pending';\n  let state = null;\n  const hidden = () => documentTarget?.hidden === true;\n\n  function publish(status, code) {\n    state = Object.freeze({ productOrderId, status, ...(code ? { code } : {}) });\n    // A UI rendering error must not restart a successful account refresh or a request.\n    try { onState(state); } catch { /* The caller owns errors in its rendering callback. */ }\n  }\n\n  function clearPoll() {\n    clearTimeout(pollTimer);\n    pollTimer = null;\n  }\n\n  function stop(status, code) {\n    active = false;\n    generation += 1;\n    clearPoll();\n    clearTimeout(deadlineTimer);\n    deadlineTimer = null;\n    controller?.abort();\n    controller = null;\n    inFlight = null;\n    windowTarget?.removeEventListener('focus', resume);\n    documentTarget?.removeEventListener('visibilitychange', visibilityChanged);\n    if (status) publish(status, code);\n  }\n\n  function schedule() {\n    clearPoll();\n    if (active && !hidden()) pollTimer = setTimeout(() => { void check(); }, intervalMs);\n  }\n\n  function resume() {\n    if (active && !hidden()) void check();\n  }\n\n  function visibilityChanged() {\n    if (hidden()) clearPoll();\n    else resume();\n  }\n\n  function validate(order) {\n    if (!order || order.productOrderId !== productOrderId) return 'ORDER_MISMATCH';\n    if (order.mode !== 'live') return 'ENVIRONMENT_MISMATCH';\n    if (!['PENDING', 'PAID', 'CLOSED'].includes(order.paymentStatus)\n        || !['pending', 'active'].includes(order.entitlementStatus)\n        || (order.paymentStatus !== 'PAID' && order.entitlementStatus === 'active')) return 'INVALID_ORDER_STATUS';\n    return null;\n  }\n\n  // An adapter that ignores abort cannot block disposal/restart or publish a late result.\n  // It should still pass signal to fetch so the network request itself is also cancelled.\n  function abortable(action, signal) {\n    return new Promise((resolve, reject) => {\n      const aborted = () => {\n        signal.removeEventListener('abort', aborted);\n        const error = new Error('Payment completion request aborted');\n        error.name = 'AbortError';\n        reject(error);\n      };\n      if (signal.aborted) { aborted(); return; }\n      signal.addEventListener('abort', aborted, { once: true });\n      Promise.resolve().then(() => {\n        if (signal.aborted) throw Object.assign(new Error('Request aborted'), { name: 'AbortError' });\n        return action();\n      }).then(value => {\n        signal.removeEventListener('abort', aborted);\n        resolve(value);\n      }, error => {\n        signal.removeEventListener('abort', aborted);\n        reject(error);\n      });\n    });\n  }\n\n  /** Check immediately while running. Concurrent focus/manual checks share one request. */\n  function check() {\n    if (!active || disposed || hidden()) return Promise.resolve(state);\n    if (inFlight) return inFlight;\n    clearPoll();\n    const currentGeneration = generation;\n    const currentController = new AbortController();\n    controller = currentController;\n    const { signal } = currentController;\n    let requestTimedOut = false;\n    const requestTimer = setTimeout(() => {\n      requestTimedOut = true;\n      currentController.abort();\n    }, requestTimeoutMs);\n    const current = () => active && !disposed && generation === currentGeneration;\n\n    inFlight = (async () => {\n      try {\n        const order = await abortable(() => queryOrder(productOrderId, { signal }), signal);\n        if (!current()) return state;\n        const invalid = validate(order);\n        if (invalid) { stop('error', invalid); return state; }\n        if (order.paymentStatus === 'CLOSED') { stop('closed'); return state; }\n        lastPhase = order.paymentStatus === 'PAID' ? 'confirming' : 'pending';\n        publish(lastPhase);\n        if (!current()) return state;\n        if (order.paymentStatus === 'PAID' && order.entitlementStatus === 'active') {\n          await abortable(() => refreshAccount({ productOrderId, signal }), signal);\n          if (!current()) return state;\n          confirmed = true;\n          stop('confirmed');\n        }\n      } catch (error) {\n        if (!current()) return state;\n        if (error?.status === 401 || error?.status === 403) stop('error', 'AUTH_REQUIRED');\n        else publish(lastPhase, requestTimedOut ? 'REQUEST_TIMEOUT' : 'RETRYABLE_ERROR');\n      } finally {\n        clearTimeout(requestTimer);\n        if (generation === currentGeneration) {\n          controller = null;\n          inFlight = null;\n          schedule();\n        }\n      }\n      return state;\n    })();\n    return inFlight;\n  }\n\n  /**\n   * Start on opening the purchase UI, after creating/restoring an order, or on return.\n   * A manual button may call start() again after timeout/auth recovery; check() while\n   * running triggers an immediate check. Confirmed watchers do not refresh twice.\n   * The five-minute deadline includes hidden time and hanging requests; a timeout\n   * means automatic checks stopped, never that payment failed. Keep a manual check.\n   */\n  function start() {\n    if (disposed) throw new Error('Payment completion watcher disposed');\n    if (confirmed) return Promise.resolve(state);\n    if (active) return check();\n    active = true;\n    generation += 1;\n    publish(lastPhase);\n    if (!active || disposed) return Promise.resolve(state);\n    windowTarget?.addEventListener('focus', resume);\n    documentTarget?.addEventListener('visibilitychange', visibilityChanged);\n    deadlineTimer = setTimeout(() => stop('timeout', 'AUTOMATIC_CHECKS_STOPPED'), timeoutMs);\n    return check();\n  }\n\n  /** Final cleanup for logout/account switch/unmount. Create a new watcher to reuse. */\n  function dispose() {\n    disposed = true;\n    stop();\n  }\n\n  // onState statuses: pending, confirming, confirmed, closed, error, timeout.\n  // Codes are fixed safe strings; no upstream exception or sensitive response leaks.\n  return { start, check, dispose };\n}\n"
};
